    /// @notice Helper to read a dynamic-length bytes value from a storage slot.
    function _readStorageBytes(uint256 slot) internal view returns (bytes memory) {
        uint256 packed;
        assembly {
            packed := sload(slot)
        }

        if (packed & 0x1 == 0x1) {
            // Short data: length and data packed in the same slot.
            uint256 len = packed >> 0x1;
            bytes memory result = new bytes(len);
            uint256 data = packed >> 0x8;
            for (uint256 i = 0; i < len && i < 32; i++) {
                result[i] = bytes1(uint8(data >> (0x8 * (0x1f - i))));
            }
            return result;
        } else {
            // Long data: length in `slot`, data starting at keccak256(slot).
            uint256 len = packed;
            bytes memory result = new bytes(len);
            bytes32 dataSlot;
            assembly {
                mstore(0x00, slot)
                dataSlot := keccak256(0x00, 0x20)
            }
            for (uint256 i = 0; i < len; i += 0x20) {
                uint256 word;
                assembly {
                    word := sload(add(dataSlot, div(i, 0x20)))
                }
                uint256 chunk = len - i;
                if (chunk > 0x20) chunk = 0x20;
                for (uint256 j = 0; j < chunk; j++) {
                    result[i + j] = bytes1(uint8(word >> (0x8 * (0x1f - j))));
                }
            }
            return result;
        }
    }
}
